export default async function reminderNext(
  { events, previousState, acknowledgeEventId, timeMin, timeMax },
  context,
) {
  if (!Array.isArray(events)) throw Error("Calendar events missing");
  const saved = (await context.state.get("reminder-seen")) ?? { ids: [], pending: null };
  if (saved.pending) {
    if (acknowledgeEventId !== saved.pending)
      throw Error("Inspect Telegram and acknowledge pending event " + saved.pending);
    saved.ids.push(saved.pending);
    saved.pending = null;
    await context.state.set("reminder-seen", saved);
  }
  const index = previousState?.index ?? 0;
  if (index === events.length)
    return { state: { index }, more: false, process: false, prompt: "", eventId: "" };
  const e = events[index];
  if (typeof e?.id !== "string" || !e.id) throw Error("Event ID missing");
  const start = Date.parse(e.start?.dateTime ?? "");
  if (!Number.isFinite(start) || start < Date.parse(timeMin) || start >= Date.parse(timeMax))
    return { state: { index: index + 1 }, more: true, process: false, prompt: "", eventId: e.id };
  if (saved.ids.includes(e.id))
    return { state: { index: index + 1 }, more: true, process: false, prompt: "", eventId: e.id };
  return {
    state: { index: index + 1 },
    more: true,
    process: true,
    eventId: e.id,
    prompt: JSON.stringify({
      name: e.summary,
      description: e.description,
      location: e.location,
      start: e.start,
      end: e.end,
      creator: e.creator,
    }),
  };
}

