export default async function reminderPending({ eventId }, context) {
  const state = (await context.state.get("reminder-seen")) ?? { ids: [], pending: null };
  if (state.pending) throw Error("Existing pending reminder");
  state.pending = eventId;
  await context.state.set("reminder-seen", state);
  return { eventId };
}

