export default async function reminderDone({ eventId }, context) {
  const state = await context.state.get("reminder-seen");
  if (state?.pending !== eventId) throw Error("Reminder checkpoint mismatch");
  state.ids.push(eventId);
  state.pending = null;
  await context.state.set("reminder-seen", state);
  return { done: true };
}
